#!/usr/bin/env python3
"""Source-bound CPU evidence for campaign shader-entry stalls and dump I/O."""
import argparse
import hashlib
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('evidence', type=Path)
    f = ap.parse_args().evidence.resolve()
    m = json.loads((f / 'manifest.json').read_text())
    for name, digest in m['sources'].items():
        assert sha(ROOT / name) == digest, 'Source changed: ' + name
    for name, digest in m['evidence'].items():
        assert sha(f / name) == digest, 'Evidence changed: ' + name
    assert sha(Path(m['run']['path'])) == m['run']['sha256']
    inputs = json.loads((f / 'run-shader-inputs.json').read_text())
    for record in inputs['records']:
        assert sha(f / 'run-shaders' / record['file']) == record['sha256'], 'Input changed: ' + record['file']
    r = json.loads((f / 'bench-results.json').read_text())
    run = json.loads((f / 'run-analysis.json').read_text())
    for gate in ('focused-debug.log', 'focused-release.log'):
        assert '8/8 steps succeeded; 157/159 tests passed (2 skipped)' in (f / gate).read_text()
    summary = r['summary']
    rows = ''.join(f'<tr><td>{"Checksum sink, no delay" if key == "0" else "Sink with 20 ms requested delay per job"}</td><td>{s["before_ns"]/1e6:.3f}</td><td>{s["after_ns"]/1e6:.3f}</td><td>{s["drained_before_ns"]/1e6:.3f}</td><td>{s["drained_after_ns"]/1e6:.3f}</td></tr>' for key, s in summary.items())
    stage_rows = ''.join(f'<tr><td>{name[:-3]}</td><td>{value/1e6:.3f}</td><td>{r["stage_max_ns"][name]/1e6:.3f}</td></tr>' for name, value in r['stage_totals_ns'].items())
    evidence_rows = ''.join(f'<li>Line {row["line"]}: <code>{html.escape(row["text"])}</code></li>' for key in ('Vulkan host time by entry point:', 'VULKAN FSI RECORDING RETIREMENT:', 'PE64 BLOCK JIT TLB INVALIDATION WORK:') for row in run[key][:3])
    plot = [[s['before_ns']/1e6, s['after_ns']/1e6, s['drained_before_ns']/1e6, s['drained_after_ns']/1e6] for s in summary.values()]
    page = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rosette · Campaign shader stalls</title><style>
body{margin:0;background:#10161f;color:#e5edf7;font:17px/1.6 system-ui}main{max-width:1170px;margin:auto;padding:32px}h1{font-size:38px;line-height:1.2}h2{margin-top:34px}p{color:#bfccda}a{color:#8bdacf}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{background:#1b2838;padding:20px;border-radius:12px}.value{font-size:36px;color:#8bdacf;font-weight:750}.note{border-left:4px solid #8bdacf;background:#172230;padding:16px 22px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}td,th{padding:10px;text-align:right;border-bottom:1px solid #304153}td:first-child,th:first-child{text-align:left}code{overflow-wrap:anywhere;color:#a9dacb;font-size:14px}button{border:1px solid #455d73;border-radius:8px;background:#22374c;color:#e5edf7;padding:9px 12px;margin:4px;cursor:pointer}button[aria-pressed=true]{background:#315653;border-color:#8bdacf}svg{width:100%;background:#162332;border-radius:10px}@media(max-width:780px){main{padding:20px}.cards{grid-template-columns:1fr}h1{font-size:30px}}
</style><main><h1>Rosette campaign shader stalls</h1><p>Round 56 · campaign eb354fd884b2 · CPU-only checks · source-only delivery</p><div class="note">The log localizes repeated global stalls to shader creation. Synchronous diagnostic disk writes are a strong suspect, and are now off the caller path. Their exact live share remains unmeasured until the new stage counters run. No FPS multiplier is claimed.</div>
<div class="cards"><div class="card"><div class="value">418.4 s</div>shader-entry host time · 476 timed calls</div><div class="card"><div class="value">15</div>no-progress snapshots · repeated observations, not distinct freeze count</div><div class="card"><div class="value">20.0 ms</div>recording retirement over the entire supplied run</div></div>
<h2 id="stalls">Where the campaign stops progressing</h2><p>The largest Vulkan host entry is <code>vkCreateShaderModule</code>: 418,362 ms total, 36,010 ms maximum. Thirty-five lock-held and fifteen no-progress snapshots repeatedly name the GPU Commands worker in that call, with other threads waiting on the Windows runtime mutex. These snapshots overlap and must not be added as stall durations.</p><p>Only 70 ms was recorded in the lock-released native shader callback across 477 calls. The surrounding path also marshals, inspects, rewrites, records metadata, and writes both original and native dumps to the external drive. A host timer includes scheduling and bookkeeping; it is not a Metal compilation or GPU utilization measurement.</p><p>The previous disposal change is active: 2,752 recordings / 372,564 chunks retired in 20,010 µs total, 58 µs maximum. The cache filter skipped 2,318,802 absent directions and visited 48,585,827 actual tag slots. Those counts do not measure invalidation CPU milliseconds, but disposal does not account for the observed seconds-long shader-entry holds.</p>
<h2 id="offline">The actual rewrite stages are cheap in the offline replay</h2><p>All 308 captured FSI inputs matching module and original-fingerprint identities in this log were replayed through the production HDR → rectangle → pixel-frequency → robust rewrite chain. Fingerprints were recomputed, every refusal was none, and the code for these transforms is unchanged. This is a one-shot diagnostic timing, not a speedup comparison or a complete replay of the 477 live module calls.</p><div class="scroll"><table><tr><th>CPU stage · 308 modules</th><th>Cumulative ms</th><th>Largest module ms</th></tr>STAGES</table></div><p>Archived 1,098-module replay also took roughly 0.58 s across these four stages. Disk I/O remains a strong hypothesis for the live discrepancy; marshalling, identification, scheduling and other surrounding costs are not yet separately attributed. Shader-stage compiler acceptance is not new rendering support.</p>
<h2 id="io">Owned, bounded evidence writes outside shader creation</h2><p>A dedicated host worker now writes the same guest/native filenames and exact bytes. The caller copies each request into owned memory, enqueues it, and proceeds. No guest pointers, driver calls or GPU work run on this worker. It keeps shader bounds, transform order, native result handling and device safety unchanged.</p><p>Admission is bounded to 1,024 queued requests, 64 MiB pending shader bytes and the existing 256 MiB cumulative run quota. Queue/byte limits and allocation failures decline diagnostic evidence explicitly; they never refuse or wait on rendering. A queued dump is not considered saved until the write completes. Shutdown joins the active write, cancels queued diagnostics with counters, and joins before library unload, including libc exit. The active OS write can still delay shutdown; gameplay does not wait for it.</p>
<h2 id="measurement">Caller latency falls; the I/O itself does not become faster</h2><p>Seven alternating comparisons per case, eight 128 KiB requests per sample, all snapshots and checksums verified. The same CPU sink runs inline or on the production queue. The delayed sink requests 20 ms per job; host scheduling makes its measured completion longer. Queue setup is outside both timing windows. These are controlled callback fixtures, not measurements of your drive or Halo FPS.</p><div class="scroll"><table><tr><th>CPU fixture</th><th>Caller before ms</th><th>Caller after ms</th><th>All work before ms</th><th>All work after ms</th></tr>BENCH</table></div><p>The delayed case reduces caller occupancy from DELAY_BEFORE to DELAY_AFTER ms. All work still takes DRAIN_AFTER ms. The no-delay case discloses queue/copy overhead in total completion; moving work off the caller is not the same as reducing it.</p><button data-case="0">No-delay checksum control</button><button data-case="1">Delayed I/O fixture</button><svg id="comparison" viewBox="0 0 850 190" role="img" aria-label="Caller and complete-work CPU times"></svg>
<h2>Checks, delivery and the next normal run</h2><p>Focused Debug and ReleaseFast each pass 157/159 tests (two optional benchmark skips), 8/8 steps. Final standalone benchmark passes 24/24. Checks cover blocked-I/O production shader creation, original/native file bytes and names, source/marshal reuse, capacity and byte/run quotas, allocation failures, four concurrent producers, cancellation and active-write join. The libc-exit probe passes; reversed unload order is detected with status 2. Formatting, source-size and calling-context audits pass.</p><p>Full Zig suite, bare root <code>make shell-update</code>, installation and matched campaign verification remain deferred. No installed binary changed. Your other agent must run the long gates and install before this affects gameplay. No special game flags are required.</p><p>The next log will have <code>VULKAN SHADER HOST STAGE</code> for marshal, inspect, guest evidence, HDR, rectangle, pixel, robust, driver, native evidence and remainder. <code>VULKAN FSI EVIDENCE IO</code> reports accepted/saved/failed/limited/cancelled, pending/peak bytes and worker elapsed/max time. Neither new marker is present in the supplied run. If the dump worker accumulates seconds while caller capture stages stay small and global stalls disappear, that confirms the diagnosis. Otherwise the new stage maxima identify the remaining offender.</p><p>Queue host time remains 203.129 s including 190.944 s of room waiting; graphics pipeline creation adds a separately scoped 16.624 s, maximum 4.773 s. Timers can overlap. Useful CPU throughput and GPU/queue work still limit sustained FPS. One risk event, zero severe events and depth two remain; watchdog limits, isolation, TSO, audio, Fast Path and the 30 FPS ceiling were preserved.</p>
<details><summary>Line-numbered run evidence</summary><ul>RUN_LINE_EVIDENCE</ul></details><p><a href="../run-analysis.json">All stall snapshots and selected run lines</a> · <a href="../bench-results.json">All 28 measured samples</a> · <a href="../bench-final.log">Raw benchmark</a> · <a href="../run-stages-final.log">308-module rewrite replay</a> · <a href="../run-shader-inputs.json">Matched shader identities</a> · <a href="../manifest.json">Source / input / binary / command hashes</a> · <a href="../focused-debug.log">Debug checks</a> · <a href="../focused-release.log">ReleaseFast checks</a> · <a href="../exit-1.log">Exit proof</a></p></main><script>
const rows=PLOT;function show(i){const [b,a,db,da]=rows[i],scale=500/Math.max(b,a,db,da);const items=[['Caller before',b,'#75899f'],['Caller after',a,'#8bdacf'],['All work before',db,'#75899f'],['All work after',da,'#8bdacf']];document.getElementById('comparison').innerHTML=items.map(([name,time,color],n)=>`<text x="18" y="${32+n*43}" fill="#bfccda">${name}</text><rect x="168" y="${13+n*43}" width="${time*scale}" height="25" fill="${color}"/><text x="${178+time*scale}" y="${32+n*43}" fill="#e5edf7">${time.toFixed(3)} ms</text>`).join('');document.querySelectorAll('[data-case]').forEach(x=>x.setAttribute('aria-pressed',+x.dataset.case===i))}document.querySelectorAll('[data-case]').forEach(x=>x.onclick=()=>show(+x.dataset.case));show(1);
</script></html>'''
    slow = summary['20000000']
    replacements = {'STAGES': stage_rows, 'BENCH': rows, 'PLOT': json.dumps(plot), 'RUN_LINE_EVIDENCE': evidence_rows, 'DELAY_BEFORE': f'{slow["before_ns"]/1e6:.3f}', 'DELAY_AFTER': f'{slow["after_ns"]/1e6:.3f}', 'DRAIN_AFTER': f'{slow["drained_after_ns"]/1e6:.3f}'}
    for key in sorted(replacements, key=len, reverse=True):
        page = page.replace(key, replacements[key])
    (f / 'final').mkdir(exist_ok=True)
    (f / 'final/report.html').write_text(page)
    print('Rendered campaign stall report; hashes and focused gates verified.')

if __name__ == '__main__':
    main()
